    for (rr, cc) in template:
        top = top0 + rr * spacing
        if st <= top < st + sb:
            x = minx + cc * spacing
            for (dr, dc) in template:
                out[top+dr][x+dc] = 2
            shapes.append((top, x))
    shapes.sort()
    for i, (top, x) in enumerate(shapes):
        dr, dc = template[i]
        out[top+dr][x+dc] = 8
    if vertical:
        out = [[out[r][c] for r in range(H)] for c in range(W)]
    return out

